  (* LPS 727298f3: [RESF] now asks that its window be mapped ([AllocRepX.ak_resf_hi]).  The user
     map [rbeg + mu, + 262144) lies inside the primary region [PRIM] maps ([AUR]:
     mu + kUserMapSize <= kFreeArrayOffset); [rf_umap]'s recorded proof passes this lemma there. *)
  Lemma rf_umap_mc : map_contains (vm_maps (m_vmmaps mo)) (Z_to_bv 64 (rbeg + mu)) (Z_to_bv 64 262144) = true.
  Proof.
    assert (U : forall z, 0 <= z < 2 ^ 64 -> bv_unsigned (Z_to_bv 64 z) = z)
      by (intros z Hz; rewrite Z_to_bv_unsigned; apply bv_wrap_small; unfold bv_modulus; exact Hz).
    pose proof SBR as S1. pose proof AUR as A1. pose proof HC as H1.
    assert (B : AHI_LO <= sb /\ sb + 2 ^ 37 + 4096 <= aceil /\ 1 <= c <= 30 /\ 0 <= mu /\ mu + 262144 <= 3758096384)
      by (clear - S1 A1 H1; unfold kSpaceSize, kPageSize, kUserMapSize, kFreeArrayOffset in *; lia).
    clear - PRIM B U. pose proof aceil_facts as AF.
    apply PRIM; unfold rbeg; rewrite !U; unfold AHI_LO in *; lia.
  Qed.

  (* [comment removed for export] *)
  Lemma rf_umap : forall msF1 mo1, nf < n -> mu < rf_total c nf au ->
    rf2_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu fl msF1 mo1 ->
    (forall msF' mo', rf3_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu (mu + 262144) fl msF' mo' ->
                      sreach asegs Q (mkCfg msF' mo')) ->
    sreach asegs Q (mkCfg msF1 mo1).
